-- Certificates and courses

create table "public"."certificates" (
  "id" bigint primary key generated by default as identity,
  "name" varchar,
  "issuer" varchar,
  "issuer_icon" varchar,
  "date" date,
  "type" varchar,
  "tags" varchar,
  "url" varchar,
  "order" smallint,
  "user" uuid,
  "is_active" boolean not null default true,
  constraint "unique_together_user_order" unique ("user", "order")
);

alter table "public"."certificates" add constraint "certificates_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."certificates" enable row level security;
create policy "Enable read access for all users" on "public"."certificates" for select using (true);

grant all on "public"."certificates" to postgres, anon, authenticated, service_role;
